using System.Threading;
using System.Threading.Tasks;

namespace Commerce.Orders;

/// <summary>
/// Application boundary for the customer behavior that creates an order.
/// Request and result contracts remain open until their canonical semantics are defined.
/// </summary>
public interface ICreateOrderUseCase<TRequest, TResult>
{
    Task<TResult> HandleAsync(
        TRequest request,
        CancellationToken cancellationToken = default);
}

/// <summary>
/// Keeps externally visible order effects behind the application boundary.
/// Implementations own the concrete effect details.
/// </summary>
public interface ICreateOrderEffects<TRequest, TResult>
{
    Task<TResult> CreateOrderAsync(
        TRequest request,
        CancellationToken cancellationToken = default);
}

/// <summary>
/// Coordinates create-order behavior by delegating its effect through the declared port.
/// </summary>
public sealed class CreateOrderHandler<TRequest, TResult> : ICreateOrderUseCase<TRequest, TResult>
{
    private readonly ICreateOrderEffects<TRequest, TResult> _effects;

    public CreateOrderHandler(ICreateOrderEffects<TRequest, TResult> effects)
    {
        _effects = effects;
    }

    public Task<TResult> HandleAsync(
        TRequest request,
        CancellationToken cancellationToken = default)
    {
        return _effects.CreateOrderAsync(request, cancellationToken);
    }
}
